{{ config(
            materialized='table',
                post_hook={
                    "sql": "INSERT INTO SNITCH_DB.MAPLEMONK.SPEED_INVENTORY with data as ( select CASE WHEN BRANCH_CODE = 42 THEN \'SNITCH - COFO - METRO MALL\' WHEN BRANCH_CODE = 26 THEN \'SNITCH - COFO - LINKING ROAD\' WHEN BRANCH_CODE = 68 THEN \'SNITCH - COFO - DAHISAR\' WHEN BRANCH_CODE = 142 THEN \'SNITCH - COCO - HINJAWADI PHASE -1\' WHEN BRANCH_CODE = 23 THEN \'SNITCH - COFO - TRIBECA\' WHEN BRANCH_CODE = 38 THEN \'SNITCH - COFO - BANER\' WHEN BRANCH_CODE = 90 THEN \'SNITCH - COCO - JANAKPURI\' WHEN BRANCH_CODE = 106 THEN \'SNITCH - COCO - MOTI NAGAR\' WHEN BRANCH_CODE = 49 THEN \'SNITCH - COCO - LAJPAT NAGAR\' WHEN BRANCH_CODE = 82 THEN \'SNITCH - COCO - FARIDABAD\' WHEN BRANCH_CODE = 73 THEN \'SNITCH - COCO - SECTOR-29\' WHEN BRANCH_CODE = 85 THEN \'SNITCH - COCO - SECTOR-50\' WHEN BRANCH_CODE = 77 THEN \'SNITCH - COFO - TOLICHOWKI\' WHEN BRANCH_CODE = 47 THEN \'SNITCH - COFO - KOTHAPET\' WHEN BRANCH_CODE = 125 THEN \'SNITCH - COFO - HIMAYAT NAGAR\' WHEN BRANCH_CODE = 103 THEN \'SNITCH - FOCO - SINDHUBHAVAN\' WHEN BRANCH_CODE = 18 THEN \'SNITCH - FOCO - SHYAMAL\' WHEN BRANCH_CODE = 134 THEN \'SNITCH - COCO - CG ROAD\' WHEN BRANCH_CODE = 102 THEN \'SNITCH - FOCO - BOPAL\' WHEN BRANCH_CODE = 39 THEN \'SNITCH - FOCO - VAISHALI NAGAR\' WHEN BRANCH_CODE = 91 THEN \'SNITCH - FOCO - MALVIYA NAGAR\' WHEN BRANCH_CODE = 132 THEN \'SNITCH - COCO - KAMLANAGAR\' WHEN BRANCH_CODE = 114 THEN \'SNITCH - COCO - ROHINI\' WHEN BRANCH_CODE = 40 THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN BRANCH_CODE = 57 THEN \'SNITCH - COCO - BANASHANKARI\' WHEN BRANCH_CODE = 14 THEN \'SNITCH - COCO - BEL ROAD\' else null end as store, branch_code, sku, inventory_atp::INTEGER as atp, inventory_total::INTEGER as total, sku_inventory_buffer::INTEGER as sku_buffer, location_inventory_buffer::INTEGER as location_buffer, location_visible, enabled, location, query_hour_ist::DATE as saved_date from snitch_db.maplemonk.s3_product_inventory where store is not null and sku not like \'8%\' and sku not like \'%CB%\' and sku not like \'%HANG%\' and sku not like \'%UNI%\' and sku not like \'%NT%\' and sku not like \'%GIFT%\' ) , buffer as ( select sku_group, branch_code from snitch_db.maplemonk.omni_buffer_skus ), item_master as ( select sku as s1, b.sku_group, b.branch_code as b2, \'true\' as exposure from snitch_db.maplemonk.uc_final_item_master u left join buffer b on u.skugroup = b.sku_group where sku_group is not null ) , correct_inv as ( select branch_code, location, location_visible, sku, sum(total) as total, from data group by 1,2,3,4 ), buffermaths as ( select c.* , CASE WHEN b.exposure = \'true\' and lower(location) not like \'%front%\' then \'true\' WHEN b.exposure = \'true\' and lower(location) like \'%front%\' then \'front\' else \'not_in_list\' end as exposure from correct_inv c left join item_master b on CONCAT(c.branch_code,c.sku) = CONCAT(b.b2,b.s1) ), uc as (select sku, category_code, skugroup, shopify_status, sku_class, sales_last_7_days, sales_last_15_days, sales_last_30_days, natural_ros from snitch_db.maplemonk.uc_final_item_master) select CASE WHEN BRANCH_CODE = 42 THEN \'SNITCH - COFO - METRO MALL\' WHEN BRANCH_CODE = 26 THEN \'SNITCH - COFO - LINKING ROAD\' WHEN BRANCH_CODE = 68 THEN \'SNITCH - COFO - DAHISAR\' WHEN BRANCH_CODE = 142 THEN \'SNITCH - COCO - HINJAWADI PHASE -1\' WHEN BRANCH_CODE = 23 THEN \'SNITCH - COFO - TRIBECA\' WHEN BRANCH_CODE = 38 THEN \'SNITCH - COFO - BANER\' WHEN BRANCH_CODE = 90 THEN \'SNITCH - COCO - JANAKPURI\' WHEN BRANCH_CODE = 106 THEN \'SNITCH - COCO - MOTI NAGAR\' WHEN BRANCH_CODE = 49 THEN \'SNITCH - COCO - LAJPAT NAGAR\' WHEN BRANCH_CODE = 82 THEN \'SNITCH - COCO - FARIDABAD\' WHEN BRANCH_CODE = 73 THEN \'SNITCH - COCO - SECTOR-29\' WHEN BRANCH_CODE = 85 THEN \'SNITCH - COCO - SECTOR-50\' WHEN BRANCH_CODE = 77 THEN \'SNITCH - COFO - TOLICHOWKI\' WHEN BRANCH_CODE = 47 THEN \'SNITCH - COFO - KOTHAPET\' WHEN BRANCH_CODE = 125 THEN \'SNITCH - COFO - HIMAYAT NAGAR\' WHEN BRANCH_CODE = 103 THEN \'SNITCH - FOCO - SINDHUBHAVAN\' WHEN BRANCH_CODE = 18 THEN \'SNITCH - FOCO - SHYAMAL\' WHEN BRANCH_CODE = 134 THEN \'SNITCH - COCO - CG ROAD\' WHEN BRANCH_CODE = 102 THEN \'SNITCH - FOCO - BOPAL\' WHEN BRANCH_CODE = 39 THEN \'SNITCH - FOCO - VAISHALI NAGAR\' WHEN BRANCH_CODE = 91 THEN \'SNITCH - FOCO - MALVIYA NAGAR\' WHEN BRANCH_CODE = 132 THEN \'SNITCH - COCO - KAMLANAGAR\' WHEN BRANCH_CODE = 114 THEN \'SNITCH - COCO - ROHINI\' WHEN BRANCH_CODE = 40 THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN BRANCH_CODE = 57 THEN \'SNITCH - COCO - BANASHANKARI\' WHEN BRANCH_CODE = 14 THEN \'SNITCH - COCO - BEL ROAD\' else null end as store, m.*, uc.category_code, uc.skugroup, uc.shopify_status, uc.sku_class, uc.sales_last_7_days, uc.sales_last_15_days, uc.sales_last_30_days, uc.natural_ros, current_date as saved_date from buffermaths m left join uc on m.sku = uc.sku ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SPEED_ORDER_PROCESSING AS WITH orders AS ( SELECT awb, facility_switch, store_name, region, cluster, channel_order_number, branch_code, order_status, created_at, cancelled_at, NULLIF(cancelled_by, \'\') AS cancelled_by, NULLIF(cancelled_reason, \'\') AS cancelled_reason, pick_list_created_at, packed_at, manifested_at, dispatched_at, tat, sku, total_price, payment_method, category, allocation_rule_id, location, quantity FROM snitch_db.maplemonk.omni_order_processing_meta WHERE branch_code IN ( \'142\',\'38\',\'23\',\'49\',\'73\',\'82\',\'85\',\'90\',\'106\', \'114\',\'132\',\'57\',\'14\',\'68\',\'26\',\'42\',\'103\',\'18\',\'134\',\'102\' ) AND created_at::DATE >= CURRENT_DATE - 30 ), edd AS ( SELECT * FROM snitch_db.maplemonk.app_edd_data ), j1 AS ( SELECT o.*, NULLIF(e.max_edd, \'\')::TIMESTAMP AS app_edd FROM orders o LEFT JOIN edd e ON o.channel_order_number = e.shopify_order_number ), cp AS ( SELECT awb_number, assigned_date, pickup_date, delivery_date, outfordelivery_date, out_for_delivery_attempts, status, courier_partner, max_sla, min_sla, edd_cp, invoice_value, pincode, mapped_city, mapped_state, pickup_pincode, rto_mark_date FROM snitch_db.maplemonk.cp_1 WHERE mode = \'Forward\' AND assigned_date >= CURRENT_DATE - 30 ), draft AS ( SELECT o.*, c.assigned_date, c.pickup_date, c.delivery_date, c.outfordelivery_date, c.out_for_delivery_attempts, c.status, c.courier_partner, c.max_sla, c.min_sla, c.edd_cp, c.invoice_value, c.pincode, c.mapped_city, c.mapped_state, c.pickup_pincode, c.rto_mark_date FROM j1 o LEFT JOIN cp c ON o.awb = c.awb_number ), final AS ( SELECT d.*, d.created_at::DATE AS created_date_ist, d.created_at::TIME AS created_time_ist, DATEDIFF(day, d.created_at::DATE, d.app_edd::DATE) AS delivery_eta, DATEADD( minute, 690, d.app_edd::DATE ) AS sdd_cutoff_ts, CASE WHEN d.created_at::TIME >= \'11:00:00\'::TIME AND d.created_at::TIME < \'17:00:00\'::TIME THEN DATEADD(minute, 1050, d.created_at::DATE) ELSE DATEADD(minute, 690, DATEADD(day, 1, d.created_at::DATE)) END AS ndd_cutoff_ts, CURRENT_TIMESTAMP() AS now_ist, d.pickup_date AS effective_handover_ts FROM draft d WHERE d.app_edd IS NOT NULL AND DATEDIFF(day, d.created_at::DATE, d.app_edd::DATE) IN (0, 1) AND LOWER(COALESCE(d.courier_partner, \'\')) NOT LIKE \'%hld%\' AND LOWER(COALESCE(d.courier_partner, \'\')) NOT LIKE \'%pidge%\' AND LOWER(COALESCE(d.courier_partner, \'\')) NOT LIKE \'%porter%\' ) SELECT f.*, CASE WHEN f.delivery_eta = 0 THEN CASE WHEN f.manifested_at IS NOT NULL AND f.manifested_at <= f.sdd_cutoff_ts THEN \'SDD PROCESSING ADHERED\' WHEN f.manifested_at IS NULL AND f.now_ist <= f.sdd_cutoff_ts THEN \'SDD PROCESSING PENDING\' WHEN ( f.manifested_at IS NULL AND f.now_ist > f.sdd_cutoff_ts ) OR ( f.manifested_at IS NOT NULL AND f.manifested_at > f.sdd_cutoff_ts ) THEN \'SDD PROCESSING BREACHED\' END WHEN f.delivery_eta = 1 THEN CASE WHEN f.manifested_at IS NOT NULL AND f.manifested_at <= f.ndd_cutoff_ts THEN \'NDD PROCESSING ADHERED\' WHEN f.manifested_at IS NULL AND f.now_ist <= f.ndd_cutoff_ts THEN \'NDD PROCESSING PENDING\' WHEN ( f.manifested_at IS NULL AND f.now_ist > f.ndd_cutoff_ts ) OR ( f.manifested_at IS NOT NULL AND f.manifested_at > f.ndd_cutoff_ts ) THEN \'NDD PROCESSING BREACHED\' END END AS sla_status, CASE WHEN f.effective_handover_ts IS NULL THEN \'HANDOVER PENDING\' WHEN f.delivery_eta = 0 THEN CASE WHEN f.effective_handover_ts > f.sdd_cutoff_ts THEN \'HANDOVER BREACHED\' ELSE \'HANDOVER COMPLETED\' END WHEN f.delivery_eta = 1 THEN CASE WHEN f.effective_handover_ts > f.ndd_cutoff_ts THEN \'HANDOVER BREACHED\' ELSE \'HANDOVER COMPLETED\' END END AS handover_status, CASE WHEN f.delivery_date IS NULL THEN \'NOT DELIVERED\' WHEN f.delivery_date::DATE <= f.app_edd::DATE THEN \'DELIVERY ADHERED\' ELSE \'DELIVERY BREACHED\' END AS delivery_status, CASE WHEN sla_status ILIKE \'%BREACHED%\' THEN sla_status WHEN handover_status = \'HANDOVER BREACHED\' THEN handover_status WHEN delivery_status = \'DELIVERY BREACHED\' THEN delivery_status WHEN sla_status ILIKE \'%PENDING%\' THEN sla_status WHEN handover_status = \'HANDOVER PENDING\' THEN handover_status ELSE \'WITHIN TAT\' END AS rca FROM final f;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            